import React from 'react'
import Image from 'next/image'

//font
import {DM_Sans} from "next/font/google";
const DMsansFont = DM_Sans({
  subsets: ["latin"],
})

const Hero = () => {
  return (
    <section className={`${DMsansFont.className} min-h-screen bg-amber-100`}>
      <h1>MitraAI</h1>
      <h5>Your friend in need</h5>
        <Image
          src="/MitraAILogo.svg" 
          alt="MitraAI logo"
          width={100}
          height={100}
        />
    </section>
  )
}

export default Hero